window.CERT_DATA=window.CERT_DATA||{};window.CERT_DATA['bigdata-10']={"round":10,"cert":"bigdata","questions":[{"id":"6a6a00651bbde79cd2c72c1c","number":1,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 중에서 다른 정보와 결합할 경우 본래의 개인을 다시 식별해 낼 수 있는 정보에 해당하는 것은?</p>","choices":[{"n":1,"html":"익명정보"},{"n":2,"html":"가명정보"},{"n":3,"html":"개인정보"},{"n":4,"html":"민감정보"}],"answer":[2],"explain":{"mine":"<p><b>가명정보</b>는 추가 정보(다른 정보)와 결합하면 본래의 개인을 다시 알아볼 수 있는 정보입니다. 익명정보는 어떤 수단으로도 재식별이 불가능한 정보라 개인정보 보호법의 적용을 받지 않고, 가명정보는 재식별 가능성이 남아 있어 법의 규율을 받습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c1f","number":2,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>어떤 확률변수 X로부터 표본 데이터 (100, 200, 300)을 추출하였다. 이 데이터의 Z-score를 y=ax+b 형태의 그래프로 나타낼 때, a+b의 값을 구하면? (단, 표본 데이터를 독립변수(x)로, Z-score 값을 종속변수(y)로 한다)</p>","choices":[{"n":1,"html":"1.9"},{"n":2,"html":"-1.99"},{"n":3,"html":"1.99"},{"n":4,"html":"-1.9"}],"answer":[2],"explain":{"mine":"<p>표본 (100, 200, 300)의 평균은 200, 표본표준편차는 √((100²+0²+100²)/2) = √10000 = 100입니다. Z = (x−200)/100 = 0.01x − 2이므로 a = 0.01, b = −2, a+b = <b>−1.99</b>입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c14","number":3,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 시대에 나타나는 역기능 가운데 책임원칙 훼손의 사례로 볼 수 있는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"SNS에서 사용자가 스스로 자신의 일상을 공유하고, 다른 사용자들이 여기에 공감하는 댓글을 남김"},{"n":2,"html":"일상생활 곳곳에서 이루어지는 빅브라더식 감시"},{"n":3,"html":"CCTV로 촬영한 영상에서 얼굴, 차량 번호판, 이름표 등 개인 신원을 알아볼 수 있는 요소를 비식별화 처리한 뒤 배포"},{"n":4,"html":"대출이 거절되거나 낮은 신용등급을 받은 소비자에게 그 이유를 기계학습 기반 클러스터링 분석 결과라고 답변함"}],"answer":[4],"explain":{"mine":"<p>대출 거절 사유를 '기계학습 클러스터링 결과'라고만 답하는 것은, 개인이 자신의 행위가 아닌 <b>알고리즘의 예측·분류 때문에 불이익</b>을 받는 상황이므로 책임원칙 훼손의 사례입니다(4번). 빅브라더식 감시(2번)는 사생활 침해에 해당하고, 3번은 오히려 바람직한 비식별화 조치입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c1b","number":4,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 데이터 유형에 관한 설명으로 옳지 않은 것은?</p>","choices":[{"n":1,"html":"반정형 데이터는 일단 수집되면 그 형태나 구조를 바꿀 수 없다."},{"n":2,"html":"비정형 데이터는 구조화되어 있지 않고 정해진 형식이 없어, 분석에 앞서 전처리 과정을 거쳐야 한다."},{"n":3,"html":"정형 데이터는 다른 유형과 비교했을 때 구조가 명확하고 정제되어 있으며 저장과 검색이 빨라 분석하기에 용이하다."},{"n":4,"html":"반정형 데이터는 의미를 부여함으로써 시맨틱(Semantic) 데이터로 변환이 가능하다."}],"answer":[1],"explain":{"mine":"<p>반정형 데이터(XML·JSON 등)는 파싱과 변환을 거쳐 정형 구조로 바꾸는 등 <b>형태·구조의 변환이 얼마든지 가능</b>합니다. '한번 수집되면 바꿀 수 없다'는 1번이 옳지 않습니다. 의미를 부여해 시맨틱 데이터로 변환할 수 있다는 4번은 맞는 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c1d","number":5,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 비식별화 기법 가운데 총계처리(Aggregation) 기법에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"별도의 복잡한 알고리즘을 추가하지 않고도 구현할 수 있다."},{"n":2,"html":"그룹의 데이터 규모가 지나치게 작으면 그룹에 속한 각 요소의 개인정보를 추정할 가능성이 있다."},{"n":3,"html":"개별 데이터는 확인할 수 없으나 집단 수준의 통계분석은 가능하며, 과도하게 그룹화하면 정보의 가치가 떨어진다."},{"n":4,"html":"개인정보에 해당하는 데이터가 수치 데이터일 경우에는 적용이 불가능하다."}],"answer":[4],"explain":{"mine":"<p>총계처리는 합계·평균·빈도처럼 <b>수치 데이터를 집계</b>하는 기법이므로 '수치 데이터에는 적용 불가능'이라는 4번이 옳지 않습니다. 오히려 수치형에 가장 자연스럽게 적용되는 방법이며, 그룹이 너무 작으면 개인 추정 위험이 생긴다는 2번은 맞습니다.</p>"}},{"id":"6a6a00641bbde79cd2c72c0e","number":6,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석을 수행하기 위한 조직 구성 유형 가운데 집중형 구조에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"데이터 전담 부서나 데이터 센터와 같은 특정 부서에 역량이 모여 있는 형태이다."},{"n":2,"html":"주로 데이터 분석 초기 단계에서 활용되며, 전사적 차원의 통합 전략이 중요한 상황에서 이용된다."},{"n":3,"html":"관련 현업 부서와의 협업이나 분석 수행 업무를 반영하는 속도가 매우 빠르다."},{"n":4,"html":"데이터 분석 역량이 한 곳에 집결되어 있어 전문성이 높다는 특징이 있다."}],"answer":[3],"explain":{"mine":"<p>집중형 구조는 분석 조직과 현업 부서가 분리되어 있어 <b>현업과의 협업·요구 반영 속도가 느린 편</b>입니다. '매우 빠르다'는 3번이 옳지 않습니다. 역량 집결로 전문성이 높고, 전사 통합 전략이 중요한 초기 단계에 적합하다는 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c13","number":7,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>딥러닝 분야에서 널리 활용되는 학습 기법으로, 사전에 학습을 마친 모델이 갖고 있는 지식을 유사한 다른 문제 해결에 활용하는 방식을 가리키는 용어는?</p>","choices":[{"n":1,"html":"앙상블 학습(Ensemble Learning)"},{"n":2,"html":"전이 학습(Transfer Learning)"},{"n":3,"html":"준지도 학습(Semi-supervised Learning)"},{"n":4,"html":"강화 학습(Reinforcement Learning)"}],"answer":[2],"explain":{"mine":"<p>사전 학습된 모델의 지식을 유사한 다른 문제에 가져다 쓰는 기법은 <b>전이 학습(Transfer Learning)</b>입니다. 대규모 데이터로 학습한 모델을 가져와 소량의 데이터로 미세조정(Fine-tuning)하는 방식이 대표적입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c19","number":8,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 분석 도구에 관한 다음 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"어떤 데이터 분석 분야인지, 주로 어떤 목적으로 사용하는지에 따라 요구되는 데이터 분석 도구와 기술은 달라진다."},{"n":2,"html":"머신러닝과 인공지능 분야에서는 Python, Jupyter Notebook, Google Colab 등이 주로 활용된다."},{"n":3,"html":"경영 의사결정 지원, 매출 및 비용 분석 등을 위한 비즈니스 분석 도구로는 Excel, Power BI, Tableau, SQL 등이 주로 쓰인다."},{"n":4,"html":"데이터 분석을 위한 도구로는 일반적으로 JDBC와 OLTP가 주로 활용된다."}],"answer":[4],"explain":{"mine":"<p>JDBC는 자바의 DB 접속 인터페이스, OLTP는 온라인 거래 처리 시스템으로 둘 다 <b>데이터 분석 도구가 아닙니다</b>(4번이 답). 머신러닝에는 Python·Jupyter·Colab, 비즈니스 분석에는 Excel·Power BI·Tableau·SQL이 쓰인다는 설명은 맞습니다.</p>"}},{"id":"6a6a00641bbde79cd2c72c0d","number":9,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 산업을 인프라 영역과 서비스 영역으로 구분할 때, 다음 중 서비스 영역에 속하는 것은?</p>","choices":[{"n":1,"html":"데이터의 수집·저장과 분석을 위한 도구"},{"n":2,"html":"데이터 정보 제공"},{"n":3,"html":"데이터 처리에 필요한 네트워크 플랫폼"},{"n":4,"html":"클라우드 아키텍처 기반의 스토리지 활용"}],"answer":[2],"explain":{"mine":"<p>빅데이터 산업에서 <b>인프라 영역</b>은 수집·저장·분석 도구, 네트워크 플랫폼, 스토리지 같은 기반 기술을 말하고, <b>서비스 영역</b>은 데이터를 활용한 정보 제공·컨설팅·교육 등을 말합니다. '데이터 정보 제공'(2번)이 서비스 영역입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c17","number":10,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석 기획(Planning) 단계에서 업무를 진행하는 절차로 가장 적절한 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"프로젝트 정의 → 비즈니스 이해 → 수행계획 수립 → 위험계획 수립"},{"n":2,"html":"비즈니스 이해 → 프로젝트 정의 → 수행계획 수립 → 위험계획 수립"},{"n":3,"html":"프로젝트 정의 → 비즈니스 이해 → 위험계획 수립 → 수행계획 수립"},{"n":4,"html":"비즈니스 이해 → 프로젝트 정의 → 위험계획 수립 → 수행계획 수립"}],"answer":[2],"explain":{"mine":"<p>분석 기획은 <b>비즈니스 이해 및 범위 설정 → 프로젝트 정의 → 수행 계획 수립 → 위험 계획 수립</b> 순서로 진행합니다(2번). 도메인을 먼저 이해해야 프로젝트를 정의할 수 있고, 수행 계획이 서야 위험 요소를 식별할 수 있습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c11","number":11,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석 환경에서 서버·스토리지·네트워크와 같은 자원의 배치, 분산 파일 시스템, 가상화 및 컨테이너 모듈(컴포넌트)로 이루어진 구성 요소는 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"인프라스트럭처 계층"},{"n":2,"html":"데이터 수집 및 저장 계층"},{"n":3,"html":"소프트웨어 계층"},{"n":4,"html":"플랫폼 계층"}],"answer":[1],"explain":{"mine":"<p>서버·스토리지·네트워크 자원의 배치, 분산 파일 시스템, 가상화·컨테이너는 <b>인프라스트럭처 계층</b>의 구성 요소입니다. 소프트웨어 계층은 수집·처리·분석·시각화 모듈, 플랫폼 계층은 자원 관리·스케줄링을 담당합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c1e","number":12,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 품질관리를 구성하는 네 가지 핵심 요소에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"완전성(Completeness) : 데이터 수집 규정을 준수하며 데이터 포맷과 형식을 완전하게 유지하는 정도"},{"n":2,"html":"정확성(Accuracy) : 데이터가 실세계의 실제 값과 정확히 일치하는 정도"},{"n":3,"html":"일관성(Consistency) : 여러 시스템과 소스 간에 데이터 값이 서로 일치하는 정도"},{"n":4,"html":"적시성(Timeliness) : 데이터가 최신 상태를 유지하며 필요한 시점에 제공되는 정도"}],"answer":[1],"explain":{"mine":"<p>완전성은 '있어야 할 데이터가 <b>누락 없이 모두 존재</b>하는 정도'입니다. '수집 규정 준수와 포맷·형식 유지'는 유효성에 가까운 설명이므로 1번이 적절하지 않습니다. 정확성·일관성·적시성의 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c15","number":13,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>개인정보보호를 위해 지켜야 할 주요 가이드라인 업무에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"데이터를 수집하는 시점부터 개인식별 정보에 대한 비식별화 조치를 철저하게 수행한다."},{"n":2,"html":"개인정보 취급 방침을 이용자가 알 수 있도록 투명하게 공개한다."},{"n":3,"html":"개인정보를 가능한 한 많이 수집해 저장하고 분석한다."},{"n":4,"html":"개인정보가 재식별되었다면 지체 없이 파기하거나 재차 비식별화 조치를 실시한다."}],"answer":[3],"explain":{"mine":"<p>개인정보는 처리 목적에 필요한 <b>최소한의 범위에서 수집</b>하는 것이 원칙입니다. '가능한 한 많이 수집·저장·분석한다'는 3번이 가이드라인에 어긋납니다. 수집 시점부터의 비식별화, 취급 방침의 투명한 공개, 재식별 시 즉시 파기·재조치는 모두 올바른 업무입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c10","number":14,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>빅데이터 분석 기획 과정에서 WBS(Work Breakdown Structure)를 설계하는 작업은 다음 중 어떤 단계에 해당하는가?</p>","choices":[{"n":1,"html":"프로젝트 계획 수립"},{"n":2,"html":"도메인 이슈 도출"},{"n":3,"html":"보유 데이터 자산 확인"},{"n":4,"html":"데이터 분석 목표 수립"}],"answer":[1],"explain":{"mine":"<p>WBS(작업분해구조)는 일정·산출물·담당을 정의하는 프로젝트 관리 산출물로, <b>프로젝트 계획 수립</b> 단계에서 작성합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c18","number":15,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>사용자 요구사항을 파악하거나 창의적인 아이디어를 도출하기 위해 활용되는 아래 기법들에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"Scamper : 특정 문제의 해법을 찾기 위한 집단적이고 창의적인 발상 기법"},{"n":2,"html":"Brainstorming : 기존의 아이디어나 기술에 변형을 가해 새로운 아이디어를 만들어냄"},{"n":3,"html":"Interview : 모든 것에 질문을 제기하여 신선하고 새로운 아이디어를 구성"},{"n":4,"html":"FGI : 여러 명의 참가자(전문가)와 함께하는 그룹 토의를 거쳐 의견을 수렴"}],"answer":[4],"explain":{"mine":"<p>FGI(Focus Group Interview)는 <b>여러 전문가·참가자가 그룹 토의로 의견을 수렴</b>하는 기법이 맞습니다(4번). 나머지는 설명이 서로 뒤바뀌었습니다 — 집단적 발상 기법은 Brainstorming, 기존 아이디어 변형은 Scamper의 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c16","number":16,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>개인정보 보호법에 따른 개인정보 처리 방식에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"정보주체의 사생활 침해가 최소화되는 방식으로 개인정보를 처리한다."},{"n":2,"html":"개인정보의 보유기간이 지났거나 처리 목적이 달성되었을 때에는 본인의 동의를 받은 후 해당 개인정보를 파기한다."},{"n":3,"html":"정보주체의 권리가 침해될 가능성과 그 위험의 정도를 감안하여 개인정보를 안전하게 관리한다."},{"n":4,"html":"개인정보 처리 목적에 필요한 범위 안에서 개인정보의 정확성, 완전성 및 최신성이 보장되도록 한다."}],"answer":[2],"explain":{"mine":"<p>개인정보는 보유기간이 지나거나 처리 목적이 달성되면 <b>동의 여부와 관계없이 지체 없이 파기</b>해야 합니다. '본인 동의를 받은 후 파기한다'는 2번이 옳지 않습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c12","number":17,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 중 인공지능에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"약(Narrow) 인공지능은 자의식이 없는 인공지능으로, 영상·음성·자연어 인식 등 특정 분야에서 주로 활용된다."},{"n":2,"html":"강(General) 인공지능과 초(Super) 인공지능의 시대에는 더 이상 추가 학습이 필요하지 않다."},{"n":3,"html":"강 인공지능 단계에서는 인간과 같이 사고할 수 있는 범용적인 지능을 갖게 된다."},{"n":4,"html":"초 인공지능 단계에 이르면 인간의 지능을 압도적으로 뛰어넘는 지능을 보유하게 된다."}],"answer":[2],"explain":{"mine":"<p>강 인공지능·초 인공지능이라 해도 새로운 환경과 데이터에 대한 <b>학습은 계속 필요</b>합니다. '더 이상 추가 학습이 필요하지 않다'는 2번이 적절하지 않습니다. 약 AI(특정 분야)·강 AI(범용 사고)·초 AI(인간 초월)의 구분 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c20","number":18,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터의 구조 및 성격 측면에서 살펴본 데이터웨어하우스(Data Warehouse)의 대표적인 특징에 해당하지 않는 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"주제 중심성"},{"n":2,"html":"통합성"},{"n":3,"html":"확장성"},{"n":4,"html":"시간 가변성"}],"answer":[3],"explain":{"mine":"<p>데이터웨어하우스의 4대 특징은 <b>주제 중심성, 통합성, 시계열성(시간 가변성), 비휘발성</b>입니다. 확장성(3번)은 여기에 포함되지 않습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c0f","number":19,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>다음 보기 중에서 데이터 사이언티스트가 수행하는 주요 업무에 해당하지 않는 것은?</p>","choices":[{"n":1,"html":"머신러닝 모델의 개발과 성능 평가"},{"n":2,"html":"데이터의 수집과 전처리 수행"},{"n":3,"html":"분석 결과의 시각화와 리포트 작성"},{"n":4,"html":"데이터 분석 관련 인력 관리, 경영 전략 수립 및 투자 결정"}],"answer":[4],"explain":{"mine":"<p>데이터 사이언티스트의 주요 업무는 데이터 수집·전처리, 모델 개발·평가, 결과 시각화·리포팅입니다. <b>인력 관리, 경영 전략 수립, 투자 결정</b>(4번)은 경영진 또는 관리자(CDO 등)의 업무 영역입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c1a","number":20,"category":"빅데이터 분석 기획","type":"choice","subject":"<p>데이터 수집 기술과 그에 해당하는 데이터 유형을 짝지은 것 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"RSS : 뉴스, 블로그 등의 업데이트된 콘텐츠 데이터"},{"n":2,"html":"Sqoop : 관계형 데이터베이스의 정형 데이터"},{"n":3,"html":"FTP : 웹로그 데이터"},{"n":4,"html":"Flume : 실시간 로그 데이터"}],"answer":[3],"explain":{"mine":"<p>FTP는 파일 송수신 프로토콜이라 <b>실시간으로 쌓이는 웹로그 수집에는 부적절</b>합니다(3번이 답). 웹로그·실시간 로그 수집에는 Flume, Scribe, Chukwa 같은 로그 수집기를 씁니다. RSS(콘텐츠 구독), Sqoop(RDB 정형 데이터), Flume(실시간 로그)의 짝은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c24","number":21,"category":"빅데이터 탐색","type":"choice","subject":"<p>Lasso 기법이 Ridge 기법과 비교했을 때 탐색할 수 있는 해가 희소(Sparse)하게 나타나는 주요한 이유로 옳은 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"모든 변수를 모델에 반영하도록 가중치 값을 점진적으로 증가시키는 방식이기 때문이다."},{"n":2,"html":"L1 규제가 가중치 벡터의 절댓값 합에 패널티를 부과하여 일부 특성의 가중치를 강제로 0으로 만들기 때문이다."},{"n":3,"html":"오차를 0으로 만들어 중요하지 않은 변수들만 남기기 때문이다."},{"n":4,"html":"가중치가 0에 가까워지는 특성을 반영하는 L2 규제를 적용하기 때문이다."}],"answer":[2],"explain":{"mine":"<p>라쏘의 <b>L1 규제는 가중치의 절댓값 합</b>에 페널티를 주는데, 이 규제의 기하학적 특성(마름모꼴 제약 영역의 꼭짓점) 때문에 일부 가중치가 정확히 0이 되어 희소한 해가 만들어집니다(2번). 릿지의 L2 규제는 가중치를 0에 가깝게 줄일 뿐 0으로 만들지는 못합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2b","number":22,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 상관계수에 관한 설명으로 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"피어슨 상관계수는 이상치가 존재해도 값이 크게 달라지지 않으므로 이상치에 강건하다."},{"n":2,"html":"두 변수 사이에 한 변수가 다른 변수에 영향을 주는 인과관계가 존재할 때, 상관계수를 산출하여 분석한다."},{"n":3,"html":"스피어만 상관계수는 순위에 기반하므로 두 변수 간의 비선형적 관계도 측정할 수 있다."},{"n":4,"html":"켄달 상관계수는 두 변수의 순위에서 일치하는 쌍과 불일치하는 쌍의 비율을 토대로 측정하며, 표본 수가 적을 때 안정적이다."}],"answer":[1],"explain":{"mine":"<p>피어슨 상관계수는 평균·분산 기반이라 <b>이상치에 민감</b>합니다. '이상치에 강건하다'는 1번이 옳지 않습니다. 순위 기반인 스피어만·켄달 상관계수가 이상치에 상대적으로 강건한 대안입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c21","number":23,"category":"빅데이터 탐색","type":"choice","subject":"<p>데이터 정제(Data Cleaning)에 관한 설명 중 가장 적절한 것은 무엇인가?</p>","choices":[{"n":1,"html":"데이터 분석에 앞서 이상치, 결측치, 중복, 오타, 형식 오류 등을 찾아내어 수정하거나 삭제하는 과정이다."},{"n":2,"html":"보안 강화를 목적으로 데이터를 암호화하는 작업이다."},{"n":3,"html":"데이터를 시각화하여 통계적 결과를 이끌어내는 과정이다."},{"n":4,"html":"머신러닝 모델의 훈련을 위한 알고리즘을 고르는 과정이다."}],"answer":[1],"explain":{"mine":"<p>데이터 정제는 분석 전에 <b>이상치·결측치·중복·오타·형식 오류를 찾아 수정·삭제</b>하는 과정입니다(1번). 암호화(보안), 시각화, 알고리즘 선택은 정제와 다른 단계의 작업입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c28","number":24,"category":"빅데이터 탐색","type":"choice","subject":"<p>수집한 데이터에 불균형(Imbalanced Data) 문제가 발생했을 때 적용하는 샘플링 기법에 관한 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"양쪽표집(Both Sampling)은 오버 샘플링과 언더 샘플링을 함께 적용해 균형 잡힌 학습 데이터를 만드는 방법이다."},{"n":2,"html":"일반적으로 전체 데이터 중 일부를 무작위로 추출하거나 제거하는 방식으로 학습 데이터를 구성한다."},{"n":3,"html":"오버 샘플링 방법보다 언더 샘플링이 분석모형의 성능 면에서 우수한 경우도 있다."},{"n":4,"html":"SMOTE는 소수 클래스의 데이터를 단순 복제하여 증가시켜 데이터 불균형을 해결하는 오버 샘플링 기법이다."}],"answer":[4],"explain":{"mine":"<p>SMOTE는 단순 복제가 아니라 소수 클래스 표본과 그 이웃 사이를 <b>보간(interpolation)해 새로운 가상 데이터를 합성</b>하는 기법입니다. '단순 복제하여 증가시킨다'는 4번이 옳지 않습니다 — 단순 복제는 랜덤 오버샘플링에 대한 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c30","number":25,"category":"빅데이터 탐색","type":"choice","subject":"<p>어떤 시행에서 성공할 확률이 p인 베르누이 시행을 서로 독립적으로 n회 수행하고, 이때의 성공 횟수를 확률변수 X라 하면 X는 이항분포를 따른다. 이항분포에 관한 설명 중 옳은 것을 고르시오.</p>","choices":[{"n":1,"html":"확률변수 X의 분산은 np(1-p)로 주어진다."},{"n":2,"html":"실패할 확률은 성공확률 p와 같은 값이다."},{"n":3,"html":"확률변수 X의 평균은 p(1-p)로 주어진다."},{"n":4,"html":"확률변수 X가 가질 수 있는 값의 범위는 1부터 n까지이다."}],"answer":[1],"explain":{"mine":"<p>이항분포 B(n, p)의 <b>분산은 np(1−p)</b>가 맞습니다(1번). 평균은 np이고(3번 오답), 실패 확률은 1−p이며(2번 오답), X의 범위는 0부터 n까지입니다(4번 오답 — 0회 성공도 가능).</p>"}},{"id":"6a6a00651bbde79cd2c72c23","number":26,"category":"빅데이터 탐색","type":"choice","subject":"<p>변수 선택(Variable Selection) 기법에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"변수들 간의 다중공선성을 점검한 뒤 중복되는 변수를 제거한다."},{"n":2,"html":"Wrapper 기법은 독립변수 조합을 달리하며 모형을 구축하고, 예측 성능 평가를 통해 독립변수를 선정한다."},{"n":3,"html":"상호 정보량(Mutual Information)을 활용하면 변수와 타깃 간의 비선형 관계까지 측정할 수 있다."},{"n":4,"html":"Filter 기법은 모델을 적용하기 전에 교차검증을 수행한다."}],"answer":[4],"explain":{"mine":"<p>필터 기법은 모델 학습이나 교차검증 <b>없이</b> 상관계수·카이제곱 같은 통계량만으로 변수를 선별하는 방법입니다. '모델 적용 전에 교차검증을 수행한다'는 4번이 옳지 않습니다. 교차검증으로 성능을 평가하며 변수를 고르는 것은 래퍼 기법입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2e","number":27,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률변수 X가 P(X=1)=p, P(X=-1)=1-p를 따른다고 하자. 이 분포에서 샘플 2개 (x₁, x₂)를 무작위로 추출한 뒤 평균 y=(x₁+x₂)/2를 계산할 때, y가 취할 수 있는 각 값에 대한 확률로 옳은 것은?</p>","choices":[{"n":1,"html":"P(Y=-1)=p², P(Y=0)=2p(1-p), P(Y=1)=(1-p)²"},{"n":2,"html":"P(Y=-1)=p², P(Y=0)=p(1-p), P(Y=1)=(1-p)²"},{"n":3,"html":"P(Y=-1)=(1-p)², P(Y=0)=p(1-p), P(Y=1)=p²"},{"n":4,"html":"P(Y=-1)=(1-p)², P(Y=0)=2p(1-p), P(Y=1)=p²"}],"answer":[4],"explain":{"mine":"<p>Y=1이 되려면 두 표본 모두 1이어야 하므로 p², Y=−1이려면 둘 다 −1이어야 하므로 (1−p)², Y=0은 (1,−1) 또는 (−1,1)의 두 경우라 2p(1−p)입니다. 따라서 <b>4번</b>이 옳습니다. 세 확률의 합이 1이 되는지로 검산할 수 있습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c25","number":28,"category":"빅데이터 탐색","type":"choice","subject":"<p>주성분 분석(PCA, Principal Component Analysis)에 관한 다음 설명 중 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"PCA에서 공분산 행렬의 대각선 요소는 각 변수의 분산을 의미한다."},{"n":2,"html":"PCA에서는 전체 분산의 대부분을 설명해 주는 소수의 주성분만 선택하는 것이 가능하다."},{"n":3,"html":"PCA는 분산의 합이 보존되도록 주성분을 선택하는데, 이때 가장 작은 분산부터 주성분으로 사용한다."},{"n":4,"html":"고차원 데이터를 저차원의 주성분 공간으로 선형 변환하는 행렬 기반 기법이 PCA이다."}],"answer":[3],"explain":{"mine":"<p>PCA는 <b>분산이 가장 큰 방향부터</b> 차례로 주성분을 선택합니다. '가장 작은 분산부터 사용한다'는 3번이 옳지 않습니다. 공분산 행렬의 대각 원소가 각 변수의 분산이라는 것, 소수의 주성분만으로 전체 분산 대부분을 설명할 수 있다는 것은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c22","number":29,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 중 상자 그림에 관한 설명 가운데 옳지 않은 것은? (단, Q1은 1사분위수, Q2는 2사분위수(중앙값), Q3은 3사분위수를 의미한다)</p>","choices":[{"n":1,"html":"일반적으로 이상치는 수염(Whiskers) 바깥에 점으로 나타낸다."},{"n":2,"html":"사분위수 범위는 Q1 - Q3으로 정의된다."},{"n":3,"html":"중앙값(Median)은 상자 안의 선으로 나타내며, 데이터의 중심위치를 보여준다."},{"n":4,"html":"일반적으로 수염(Whiskers)은 최솟값과 최댓값을 나타낸다."}],"answer":[2],"explain":{"mine":"<p>사분위수 범위는 <b>IQR = Q3 − Q1</b>입니다. 'Q1 − Q3'으로 정의한 2번이 옳지 않습니다. 이상치는 수염 밖의 점으로 표시하고, 수염은 통상 1.5×IQR 안쪽의 최솟값·최댓값까지 뻗습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c31","number":30,"category":"빅데이터 탐색","type":"choice","subject":"<p>초기하분포(Hypergeometric Distribution)에 관한 다음 설명 가운데 옳지 않은 것은?</p>","choices":[{"n":1,"html":"표본을 추출할 때 앞선 추출 결과가 이후 추출 결과에 영향을 준다."},{"n":2,"html":"초기하분포의 확률 계산에는 조합(Combination)이 사용된다."},{"n":3,"html":"모집단의 크기가 유한하며, 전체 항목 수와 특정 특성을 가진 항목 수가 정해져 있다."},{"n":4,"html":"각 시행은 복원추출방법에 의해 독립적으로 수행된다."}],"answer":[4],"explain":{"mine":"<p>초기하분포는 <b>비복원추출</b>을 전제로 하므로 각 시행이 독립이 아닙니다. '복원추출로 독립 수행'이라는 4번이 옳지 않습니다. 복원추출로 매 시행이 독립이면 이항분포가 됩니다. 유한 모집단, 조합 기반 확률 계산, 앞 추출이 뒤에 영향을 준다는 설명은 모두 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2c","number":31,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률분포의 왜도(Skewness)가 양수이면 분포의 꼬리는 오른쪽(값이 큰 방향)으로 길게 늘어진다. 이때 평균값, 중앙값, 최빈값 사이의 크기 관계로 옳은 것은?</p>","choices":[{"n":1,"html":"최빈값 &gt; 중앙값 &gt; 평균"},{"n":2,"html":"평균 ≃ 중앙값 ≃ 최빈값"},{"n":3,"html":"평균 &lt; 중앙값 &lt; 최빈값"},{"n":4,"html":"최빈값 &lt; 중앙값 &lt; 평균"}],"answer":[4],"explain":{"mine":"<p>양의 왜도(오른쪽 긴 꼬리)에서는 큰 값들이 평균을 끌어올려 <b>최빈값 &lt; 중앙값 &lt; 평균</b>이 됩니다. 좌우대칭이면 셋이 거의 같고, 음의 왜도면 순서가 반대가 됩니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2a","number":32,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음 그림은 나이(Chronological Age)에 따라 나타낸 평균 심장박동수(심박수, Pulse Rate)를 보여준다. 다음 설명 가운데 가장 적절하지 않은 것은?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 600 460\" width=\"600\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"나이에 따른 평균 심박수의 산점도와 회귀직선을 나타낸 그래프\"><line x1=\"80\" y1=\"30\" x2=\"80\" y2=\"380\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"80\" y1=\"380\" x2=\"580\" y2=\"380\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"74\" y1=\"380\" x2=\"80\" y2=\"380\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"68\" y=\"385\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">60</text><line x1=\"74\" y1=\"295\" x2=\"80\" y2=\"295\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"68\" y=\"300\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">80</text><line x1=\"74\" y1=\"210\" x2=\"80\" y2=\"210\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"68\" y=\"215\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">100</text><line x1=\"74\" y1=\"125\" x2=\"80\" y2=\"125\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"68\" y=\"130\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">120</text><line x1=\"74\" y1=\"40\" x2=\"80\" y2=\"40\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"68\" y=\"45\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"end\">140</text><line x1=\"80\" y1=\"380\" x2=\"80\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"80\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">0</text><line x1=\"160\" y1=\"380\" x2=\"160\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"160\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">30</text><line x1=\"240\" y1=\"380\" x2=\"240\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"240\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">60</text><line x1=\"320\" y1=\"380\" x2=\"320\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"320\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">90</text><line x1=\"400\" y1=\"380\" x2=\"400\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"400\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">120</text><line x1=\"480\" y1=\"380\" x2=\"480\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"480\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">150</text><line x1=\"560\" y1=\"380\" x2=\"560\" y2=\"386\" stroke=\"currentColor\" stroke-width=\"1.5\"/><text x=\"560\" y=\"405\" font-size=\"14\" fill=\"currentColor\" text-anchor=\"middle\">180</text><text x=\"330\" y=\"445\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\">Chronological Age(months)</text><text x=\"25\" y=\"205\" font-size=\"16\" fill=\"currentColor\" text-anchor=\"middle\" transform=\"rotate(-90 25 205)\">Pulse Rate(number/min)</text><circle cx=\"106.7\" cy=\"61.3\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"120\" cy=\"116.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"133.3\" cy=\"91\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"146.7\" cy=\"82.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"160\" cy=\"146.3\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"186.7\" cy=\"103.8\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"200\" cy=\"176\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"213.3\" cy=\"167.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"226.7\" cy=\"133.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"253.3\" cy=\"188.8\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"266.7\" cy=\"159\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"306.7\" cy=\"210\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"320\" cy=\"176\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"346.7\" cy=\"231.3\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"373.3\" cy=\"201.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"386.7\" cy=\"218.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"400\" cy=\"261\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"426.7\" cy=\"227\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"453.3\" cy=\"273.8\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"480\" cy=\"252.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"506.7\" cy=\"303.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"520\" cy=\"273.8\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"533.3\" cy=\"286.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><circle cx=\"546.7\" cy=\"337.5\" r=\"4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><line x1=\"80\" y1=\"70\" x2=\"560\" y2=\"325\" stroke=\"currentColor\" stroke-width=\"2\"/></svg></div>","choices":[{"n":1,"html":"상관계수의 절댓값이 클수록 나이와 심박수 간의 선형관계가 강하다고 판단한다."},{"n":2,"html":"나이가 증가할수록 평균 심박수는 낮아진다."},{"n":3,"html":"나이와 심박수 사이에는 음의 상관관계가 존재한다."},{"n":4,"html":"상관계수만으로도 나이에 따른 심박수 변화의 통계적 유의성을 확인할 수 있다."}],"answer":[4],"explain":{"mine":"<p>상관계수는 선형 관계의 방향과 강도를 나타낼 뿐, <b>통계적 유의성은 별도의 검정(t-검정, p-value)</b>으로 확인해야 합니다. 유의성은 표본 크기에도 좌우되므로 '상관계수만으로 유의성을 확인할 수 있다'는 4번이 적절하지 않습니다. 그림처럼 나이가 늘수록 심박수가 낮아지는 음의 상관 해석(2·3번)은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c32","number":33,"category":"빅데이터 탐색","type":"choice","subject":"<p>표본의 크기가 n≥2인 경우, 아래 설명 가운데 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"표본평균의 기댓값은 언제나 모평균과 일치한다."},{"n":2,"html":"모집단이 정규분포를 따른다면, 무작위 추출한 개별 표본 데이터들 역시 정규분포를 따른다."},{"n":3,"html":"표본의 크기가 충분히 클 경우 표본평균은 근사적으로 정규분포를 따르게 된다."},{"n":4,"html":"표본평균의 분산은 항상 모분산보다 크다."}],"answer":[4],"explain":{"mine":"<p>표본평균의 분산은 σ²/n으로, n≥2이면 모분산 σ²보다 항상 <b>작아집니다</b>. '항상 크다'는 4번이 옳지 않습니다. 표본평균의 기댓값 = 모평균(불편성), 정규 모집단의 표본은 정규분포, 큰 표본에서 표본평균의 근사 정규성(중심극한정리)은 모두 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c34","number":34,"category":"빅데이터 탐색","type":"choice","subject":"<p>다음은 직업 전환에 영향을 주는 변수들에 대해 가설검정을 실시하여 얻은 검정통계량과 유의확률 값을 정리한 것이다. 이에 관한 설명으로 가장 적절한 것은? (단, 유의수준(α)은 0.05이다)</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><table class=\"q-tbl\"><tr><th>독립변수</th><th>검정통계량</th><th>유의확률(p-value)</th></tr><tr><td>대학 성적</td><td>2.14</td><td>0.072</td></tr><tr><td>자격증</td><td>2.51</td><td>0.035</td></tr><tr><td>경력(관련분야 근무연수)</td><td>2.44</td><td>0.041</td></tr></table></div>","choices":[{"n":1,"html":"경력은 직업 전환과 상관이 없으며 영향을 주지 않는 변수이다."},{"n":2,"html":"자격증을 보유한 사람은 자격증이 없는 사람에 비해 직업 전환 가능성이 낮다."},{"n":3,"html":"자격증은 직업 전환과 상관이 있으며 영향을 주는 변수이다."},{"n":4,"html":"대학 성적은 직업 전환과 상관이 있으며 영향을 주는 변수이다."}],"answer":[3],"explain":{"mine":"<p>유의수준 0.05보다 p-value가 작은 변수만 통계적으로 유의합니다. 자격증(0.035)과 경력(0.041)은 유의하고, 대학 성적(0.072)은 유의하지 않습니다. 따라서 3번이 적절합니다. 경력도 유의하므로 1번은 틀렸고, 검정 결과만으로는 '가능성이 낮다' 같은 방향성(2번)을 말할 수 없습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c33","number":35,"category":"빅데이터 탐색","type":"choice","subject":"<p>점추정과 구간추정에 관한 설명 중 옳은 것을 고르시오.</p>","choices":[{"n":1,"html":"신뢰구간이 넓어질수록 신뢰도는 낮아진다."},{"n":2,"html":"표준편차가 작아질수록 추정값의 오차는 커진다."},{"n":3,"html":"구간추정을 하기 전에는 점추정이 먼저 이루어져야 한다."},{"n":4,"html":"표본의 크기가 작아질수록 구간추정의 정확도는 높아진다."}],"answer":[3],"explain":{"mine":"<p>구간추정은 점추정값(예: 표본평균)을 중심으로 오차한계를 더하고 빼서 구간을 만드므로 <b>점추정이 선행</b>되어야 합니다(3번). 신뢰구간이 넓다는 건 신뢰수준이 높다는 뜻이고(1번 반대), 표준편차가 작으면 오차도 작아지며(2번 반대), 표본이 작아지면 구간이 넓어져 정확도가 떨어집니다(4번 반대).</p>"}},{"id":"6a6a00651bbde79cd2c72c26","number":36,"category":"빅데이터 탐색","type":"choice","subject":"<p>변수에 관한 다음 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"요약변수는 특정 시점에만 일시적으로 쓰이고, 파생변수는 지속적으로 활용된다."},{"n":2,"html":"파생변수는 기존 변수의 의미를 확장하거나 재구성할 때 활용된다."},{"n":3,"html":"파생변수는 기존 변수들에 수학적 계산이나 조건 등을 적용해 새로 생성한 변수이다."},{"n":4,"html":"요약변수는 여러 데이터를 그룹화한 뒤 평균, 합계, 개수 등으로 집계하여 만든 변수이다."}],"answer":[1],"explain":{"mine":"<p>통상 <b>요약변수</b>(총 구매금액, 방문 횟수 등)는 여러 분석에 두루 재활용되는 범용 변수이고, <b>파생변수</b>는 특정 분석 목적을 위해 주관적으로 만든 변수입니다. 요약변수를 '일시적', 파생변수를 '지속적'이라고 한 1번은 설명이 뒤바뀌어 적절하지 않습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2d","number":37,"category":"빅데이터 탐색","type":"choice","subject":"<p>다변량 분산분석(MANOVA)을 활용하기에 가장 알맞은 데이터는 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"(지역, 학년)에 따라 측정한 (수학, 국어, 영어) 점수"},{"n":2,"html":"(성별, 학습 방법)에 따라 측정한 국어 점수"},{"n":3,"html":"학습 방법(A, B, C)에 따른 수학 점수"},{"n":4,"html":"연령별 영어 점수"}],"answer":[1],"explain":{"mine":"<p>MANOVA(다변량 분산분석)는 <b>종속변수가 여러 개</b>일 때 집단 간 차이를 한꺼번에 검정하는 방법입니다. (수학, 국어, 영어) 세 과목 점수를 종속변수로 갖는 1번이 해당합니다. 종속변수가 하나(국어 점수, 수학 점수)인 2·3·4번은 일원/이원 분산분석의 대상입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c29","number":38,"category":"빅데이터 탐색","type":"choice","subject":"<p>확률변수 X와 Y의 공분산(Cov(X, Y)) 및 독립성에 관한 설명으로 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"확률변수 X와 Y가 서로 독립일 경우 Cov(X, Y)=0이 성립한다."},{"n":2,"html":"두 확률변수가 서로 독립이라면 공분산은 물론 상관계수도 0이 된다."},{"n":3,"html":"확률변수 X와 Y 사이에서 Cov(X, Y)=0이 성립하면 두 변수는 서로 독립이다."},{"n":4,"html":"두 확률변수가 독립인 경우, 서로에 대한 조건부 기댓값은 항상 일정하다."}],"answer":[3],"explain":{"mine":"<p>독립이면 공분산이 0이지만, <b>공분산이 0이라고 해서 독립인 것은 아닙니다</b>(3번이 옳지 않음). 공분산은 선형 관계만 잡아내므로, Y=X² 같은 비선형 종속 관계에서도 공분산이 0이 될 수 있습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c2f","number":39,"category":"빅데이터 탐색","type":"choice","subject":"<p>전체 모집단을 이질적인 여러 집단으로 구분한 뒤, 그중 일부 집단을 무작위로 뽑아 해당 집단 내 동질적인 특성을 지닌 구성원 전체(또는 일부)를 조사하는 확률적 표본추출방법은?</p>","choices":[{"n":1,"html":"단순무작위추출(Simple Random Sampling)"},{"n":2,"html":"계통표본추출(Systematic Random Sampling)"},{"n":3,"html":"층화표본추출(Stratified Random Sampling)"},{"n":4,"html":"군집추출(Cluster Random Sampling)"}],"answer":[4],"explain":{"mine":"<p>모집단을 여러 집단(군집)으로 나눈 뒤 <b>일부 군집을 무작위로 뽑아 그 안의 구성원을 조사</b>하는 방법은 <b>군집추출(Cluster Sampling)</b>입니다. 층화추출은 모든 층에서 각각 표본을 뽑지만, 군집추출은 뽑힌 군집만 조사한다는 점이 결정적 차이입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c27","number":40,"category":"빅데이터 탐색","type":"choice","subject":"<p>대형마트의 고객 데이터를 활용해 고객별 쇼핑금액을 분석하려고 한다. 다음 보기 가운데 파생변수에 해당하는 것은?</p>","choices":[{"n":1,"html":"쇼핑금액이 0원이면 비구매, 0원보다 크면 구매로 구분한 구매여부"},{"n":2,"html":"쇼핑금액 평균"},{"n":3,"html":"회원가입 시 고객이 부여받은 멤버십 등급"},{"n":4,"html":"쇼핑금액 총액"}],"answer":[1],"explain":{"mine":"<p>쇼핑금액에 '0원이면 비구매, 초과면 구매'라는 <b>조건(변환)을 적용해 새로 만든 구매여부</b>가 파생변수입니다(1번). 평균·총액은 집계로 만든 요약변수이고, 멤버십 등급은 원래부터 존재하는 원천 변수입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c3a","number":41,"category":"빅데이터 모델링","type":"choice","subject":"<p>어떤 사건의 성공확률이 p일 때, 이를 log(p/(1-p)) 형태로 자연로그를 취해 변환하였다. 이와 같은 변환을 가리키는 용어는 무엇인가?</p>","choices":[{"n":1,"html":"정규화 변환(Normalization)"},{"n":2,"html":"오즈비 변환(Odds Ratio)"},{"n":3,"html":"로짓 변환(Logit)"},{"n":4,"html":"지수 변환(Exponential)"}],"answer":[3],"explain":{"mine":"<p>성공확률 p를 log(p/(1−p))로 변환하는 것이 <b>로짓(Logit) 변환</b>입니다. 0~1 범위의 확률을 −∞~+∞ 범위로 펼쳐 선형 모형과 연결해 주며, 로지스틱 회귀의 핵심입니다. 괄호 안의 p/(1−p) 자체는 오즈(Odds)라고 부릅니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c3f","number":42,"category":"빅데이터 모델링","type":"choice","subject":"<p>시계열 데이터 분석에 활용되는 ARIMA(Autoregressive Integrated Moving Average) 모형의 ARIMA(p, d, q)에 관한 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"자기회귀(p), 차분(d), 이동평균(q)의 요소로 이루어져 있다."},{"n":2,"html":"비정상 시계열이라면 분석 전에 차분을 적용하여 정상성을 갖는 데이터로 변환한다."},{"n":3,"html":"비정상성을 지닌 시계열 데이터는 분석이 불가능하다."},{"n":4,"html":"계절성을 반영해야 하는 경우에는 seasonal ARIMA(SARIMA) 모형을 사용한다."}],"answer":[3],"explain":{"mine":"<p>비정상 시계열은 차분(d)이나 변환으로 <b>정상성을 확보한 뒤 분석하면 됩니다</b>. '분석이 불가능하다'는 3번이 옳지 않습니다. ARIMA(p, d, q)의 구성(자기회귀·차분·이동평균), 계절성에는 SARIMA를 쓴다는 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c41","number":43,"category":"빅데이터 모델링","type":"choice","subject":"<p>자연어처리 분야에서 활용되는 Attention 메커니즘에 관한 설명이 다음과 같다. 이 중 옳은 것을 모두 고르시오.</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>(가) RNN에서 나타나는 기울기 소실 문제를 극복하며, 장기 의존성 문제를 해결한다.</li><li>(나) Decoder 출력을 위해 Self-attention 방법으로 학습하여 가중치를 구하며, Encoder에서는 적용되지 않는다.</li><li>(다) 하나의 벡터에 정보가 담기면서 발생하는 정보량의 희석을 보완하며, 중요한 정보에 집중하여 이를 보존한다.</li></ul></div>","choices":[{"n":1,"html":"(가), (다)"},{"n":2,"html":"(가)"},{"n":3,"html":"(나), (다)"},{"n":4,"html":"(가), (나), (다)"}],"answer":[1],"explain":{"mine":"<p>(가) 어텐션은 장기 의존성 문제를 완화하고, (다) 하나의 고정 벡터에 모든 정보를 압축하며 생기는 정보 희석을 보완합니다 — 모두 맞습니다. (나)는 틀렸습니다. <b>셀프 어텐션은 인코더에서도 사용</b>되며(트랜스포머의 인코더가 대표적), 디코더 전용 기법이 아닙니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c35","number":44,"category":"빅데이터 모델링","type":"choice","subject":"<p>빅데이터 분석유형에 관한 설명 중 가장 적절하지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"Discovery(발견) : 분석대상과 분석방법을 모두 모르는 경우로, 명확한 목표 없이 데이터를 탐색하면서 새로운 패턴이나 관계를 발견한다."},{"n":2,"html":"Optimization(최적화) : 주어진 자원이나 조건의 범위 안에서 가장 효율적인 선택이나 결과를 이끌어낸다."},{"n":3,"html":"Insight(통찰) : 분석대상이 명확하지만 분석방법은 모르는 경우로, 기존 분석방식을 활용해 새로운 지식과 통찰을 얻는다."},{"n":4,"html":"Solution(솔루션) : 분석대상을 알고 있는 경우에 적용되며, 문제해결을 목적으로 데이터 분석을 수행해 실질적인 해결책을 제시한다."}],"answer":[3],"explain":{"mine":"<p>Insight(통찰)는 <b>분석대상(What)은 모르지만 분석방법(How)은 아는</b> 경우입니다. '분석대상이 명확하지만 방법을 모르는 경우'는 Solution에 대한 설명이므로 3번이 적절하지 않습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c3d","number":45,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 중 서포트벡터머신(Support Vector Machine) 분석모형에 관한 설명으로 옳은 것은?</p>","choices":[{"n":1,"html":"SVM은 언제나 선형 모델로만 동작하므로 복잡한 경계는 학습이 불가능하다."},{"n":2,"html":"데이터가 선형적으로 구분되지 않을 때는 독립변수를 고차원 공간으로 비선형 변환하여 분류를 수행한다."},{"n":3,"html":"본래 선형적으로 잘 구분되는 데이터라도 독립변수들을 비선형 변환하면 분류 성능이 향상된다."},{"n":4,"html":"커널 함수는 오직 선형 분류에만 사용될 수 있다."}],"answer":[2],"explain":{"mine":"<p>선형 분리가 불가능한 데이터는 <b>커널 트릭으로 고차원 공간에 매핑</b>하면 선형 분리가 가능해집니다(2번). SVM은 커널로 비선형 경계도 학습할 수 있고(1번 오답), 이미 선형으로 잘 나뉘는 데이터에 굳이 비선형 변환을 하면 오히려 과적합 위험이 생기며(3번 오답), 커널은 비선형 분류를 위한 도구입니다(4번 오답).</p>"}},{"id":"6a6a00651bbde79cd2c72c45","number":46,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래 보기에서 설명하는 최적화 알고리즘으로 옳은 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>경사하강법이 지닌 한계를 보완하기 위해 고안된 기법이다.</li><li>업데이트할 때마다 이전 기울기(변화량)의 영향을 누적 반영하여 보다 안정적이고 빠른 수렴을 유도한다.</li><li>물리학의 운동량 개념에서 아이디어를 얻어, 기울기가 진행하는 방향으로 가속도를 부여한다.</li><li>고차원 공간이나 비볼록 함수에서도 효율적으로 동작한다.</li></ul></div>","choices":[{"n":1,"html":"Nesterov Accelerated Gradient(NAG)"},{"n":2,"html":"Momentum"},{"n":3,"html":"Adaptive Moment Estimation(Adam)"},{"n":4,"html":"Adaptive Gradient Algorithm(Adagrad)"}],"answer":[2],"explain":{"mine":"<p>물리학의 운동량 개념을 빌려 <b>이전 기울기의 영향을 누적 반영해 가속</b>하는 최적화 기법은 <b>모멘텀(Momentum)</b>입니다. NAG는 여기에 '미리 가 본 위치의 기울기로 보정'하는 단계가 추가된 변형이고, Adam은 모멘텀과 적응적 학습률(RMSProp)을 결합한 것입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c43","number":47,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝의 활성화 함수에 관한 다음 설명 중 가장 옳지 않은 것은?</p>","choices":[{"n":1,"html":"소프트맥스는 다중 클래스 분류 문제의 출력층에서 흔히 활용된다."},{"n":2,"html":"시그모이드는 출력값이 0~1 사이로 매핑되므로 확률로 해석할 수 있다."},{"n":3,"html":"ReLU에서는 기울기 소실 현상이 빈번하게 나타난다."},{"n":4,"html":"ELU는 음수 구간에서도 출력을 갖도록 하여 ReLU의 dying 문제를 해소한다."}],"answer":[3],"explain":{"mine":"<p>ReLU는 양수 구간에서 기울기가 1로 유지되어 <b>기울기 소실을 완화하는 대표적인 함수</b>입니다. '기울기 소실이 빈번하다'는 3번이 옳지 않습니다. 다만 음수 입력이 계속되면 뉴런이 죽는(dying ReLU) 문제가 있고, 이를 보완한 것이 ELU·Leaky ReLU입니다(4번 맞음).</p>"}},{"id":"6a6a00651bbde79cd2c72c3b","number":48,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 중 의사결정나무 분석 모델에 관한 설명으로 옳지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"수집된 데이터의 양이 많을수록 성능이 저하된다."},{"n":2,"html":"조건에 따라 데이터를 트리 구조로 분할해 가면서 예측을 수행한다."},{"n":3,"html":"스케일링이나 정규화가 거의 필요 없어 데이터 전처리 과정이 비교적 간단하다."},{"n":4,"html":"분류(범주자료)뿐 아니라 회귀(수치자료)에도 모두 적용할 수 있다."}],"answer":[1],"explain":{"mine":"<p>의사결정나무는 데이터가 많다고 성능이 저하되는 모델이 아닙니다 — 오히려 학습에 쓸 정보가 늘어납니다. 따라서 1번이 옳지 않습니다. 트리 구조 분할, 전처리(스케일링) 부담이 적음, 분류·회귀 모두 적용 가능(CART)은 맞는 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c37","number":49,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 중 독립변수들 간 다중공선성 문제가 여전히 해소되지 않았을 때 나타나는 결과로 옳은 것은?</p>","choices":[{"n":1,"html":"의미 있는 독립변수를 선택하기가 쉬워진다."},{"n":2,"html":"독립변수들 간의 상관계수가 높게 나타난다."},{"n":3,"html":"중복된 변수를 제거하여 학습 데이터의 차원이 축소되고 계산 속도가 향상된다."},{"n":4,"html":"분석 모델이 불필요한 복잡성에서 벗어나면서 일반화 성능이 좋아진다."}],"answer":[2],"explain":{"mine":"<p>다중공선성이 남아 있다는 것은 <b>독립변수들 간 상관계수가 여전히 높게 나타난다</b>는 뜻입니다(2번). 변수 선택이 쉬워지거나(1번), 차원이 축소되거나(3번), 일반화가 좋아지는(4번) 것은 다중공선성을 '해소한 후'에 기대할 수 있는 결과입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c40","number":50,"category":"빅데이터 모델링","type":"choice","subject":"<p>딥러닝에 관한 다음 설명 가운데 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"비정형 데이터를 처리하는 데 있어 딥러닝은 강점을 지닌다."},{"n":2,"html":"은닉층에 활성화 함수가 존재하지 않으면 딥러닝은 선형변환만 가능하므로 복잡한 비선형 관계를 학습하지 못한다."},{"n":3,"html":"딥러닝은 과적합의 위험이 항상 존재하지 않으므로 정규화나 드롭아웃과 같은 기법이 불필요하다."},{"n":4,"html":"배치 정규화는 학습 과정에서 각 층의 입력 분포를 안정화함으로써 그래디언트 소실 문제를 완화하고 학습 속도를 높여준다."}],"answer":[3],"explain":{"mine":"<p>딥러닝은 파라미터가 많아 <b>과적합 위험이 항상 존재</b>하며, 그래서 규제·드롭아웃·조기종료 같은 기법이 필요합니다. 3번이 옳지 않습니다. 활성화 함수가 없으면 층을 쌓아도 선형변환에 불과하다는 것(2번), 배치 정규화의 효과(4번)는 맞는 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c47","number":51,"category":"빅데이터 모델링","type":"choice","subject":"<p>앞선 모델이 잘못 예측한 데이터를 다음 모델이 더 잘 맞추도록 순차적으로 학습시키는 방식으로, 각 모델이 이전 모델의 오차를 보완해 나가며 정확도를 점진적으로 높이는 분석 기법은?</p>","choices":[{"n":1,"html":"배깅(Bagging)"},{"n":2,"html":"부스팅(Boosting)"},{"n":3,"html":"스태킹(Stacking)"},{"n":4,"html":"보팅(Voting)"}],"answer":[2],"explain":{"mine":"<p>이전 모델이 틀린 데이터에 가중치를 높여 다음 모델이 보완하도록 <b>순차적으로 학습</b>시키는 기법은 <b>부스팅</b>입니다(AdaBoost, GBM, XGBoost 등). 배깅은 병렬 독립 학습, 스태킹은 메타 모델 결합, 보팅은 단순 투표 결합입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c46","number":52,"category":"빅데이터 모델링","type":"choice","subject":"<p>아래에 제시된 자연어 처리 기법 가운데 차원 축소를 위해 SVD(Singular Value Decomposition)를 활용하는 것은?</p>","choices":[{"n":1,"html":"Non-negative Matrix Factorization(비음수 행렬 변환)"},{"n":2,"html":"Correlated Topic Model(상관 주제 모델)"},{"n":3,"html":"Latent Dirichlet Allocation(잠재 디리클레 할당)"},{"n":4,"html":"Latent Semantic Analysis(잠재 의미 분석)"}],"answer":[4],"explain":{"mine":"<p><b>잠재 의미 분석(LSA)</b>은 단어-문서 행렬에 <b>특이값 분해(SVD)</b>를 적용해 차원을 축소하고 잠재적 의미 구조를 찾아내는 기법입니다. LDA는 확률적 토픽 모델(디리클레 분포 기반)이라 SVD를 쓰지 않습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c3e","number":53,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 덴드로그램을 참고할 때, 종속변수 값 y=5에서 형성되는 군집의 수는 몇 개인가?</p><div class=\"q-fig\"><svg class=\"q-fig__svg\" viewBox=\"0 0 500 285\" width=\"500\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Q·S·P·R 네 개체가 잎으로 놓인 계층적 군집 덴드로그램과 y=2, y=3.5, y=5 수평 점선 기준선\"><circle cx=\"170\" cy=\"245\" r=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"170\" y=\"250\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">Q</text><circle cx=\"250\" cy=\"245\" r=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"250\" y=\"250\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">S</text><circle cx=\"340\" cy=\"245\" r=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"340\" y=\"250\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">P</text><circle cx=\"420\" cy=\"245\" r=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><text x=\"420\" y=\"250\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"middle\">R</text><line x1=\"170\" y1=\"229\" x2=\"170\" y2=\"177\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"250\" y1=\"229\" x2=\"250\" y2=\"177\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"170\" y1=\"177\" x2=\"250\" y2=\"177\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"340\" y1=\"229\" x2=\"340\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"420\" y1=\"229\" x2=\"420\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"340\" y1=\"138\" x2=\"420\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"210\" y1=\"177\" x2=\"210\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"380\" y1=\"138\" x2=\"380\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"210\" y1=\"60\" x2=\"380\" y2=\"60\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"80\" y1=\"177\" x2=\"210\" y2=\"177\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-dasharray=\"5 5\"/><text x=\"72\" y=\"182\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"end\" font-style=\"italic\">y=2</text><line x1=\"80\" y1=\"138\" x2=\"380\" y2=\"138\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-dasharray=\"5 5\"/><text x=\"72\" y=\"143\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"end\" font-style=\"italic\">y=3.5</text><line x1=\"80\" y1=\"99\" x2=\"455\" y2=\"99\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-dasharray=\"5 5\"/><text x=\"72\" y=\"104\" font-size=\"15\" fill=\"currentColor\" text-anchor=\"end\" font-style=\"italic\">y=5</text></svg></div>","choices":[{"n":1,"html":"1개"},{"n":2,"html":"2개"},{"n":3,"html":"3개"},{"n":4,"html":"4개"}],"answer":[2],"explain":{"mine":"<p>절단선 y=5가 가로지르는 세로선의 개수가 군집 수입니다. 이 덴드로그램에서는 y=2와 y=3.5에서 이미 두 번의 병합이 일어나 두 덩어리가 만들어졌고, 이들이 하나로 합쳐지는 높이는 5보다 큽니다. 따라서 y=5에서는 <b>2개</b>의 군집이 형성됩니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c3c","number":54,"category":"빅데이터 모델링","type":"choice","subject":"<p>의사결정나무 분석에서 가지치기(Pruning)를 수행하는 핵심 목적으로 가장 알맞은 것은?</p>","choices":[{"n":1,"html":"분석 모델의 연산 속도를 높이기 위해 수행한다."},{"n":2,"html":"과대적합(Overfitting)을 막고, 모델의 일반화 성능을 향상시킨다."},{"n":3,"html":"모델을 더욱 깊고 복잡하게 구성함으로써 성능을 끌어올린다."},{"n":4,"html":"트리 구조를 한층 복잡하게 구성하여 다양한 패턴을 찾아낸다."}],"answer":[2],"explain":{"mine":"<p>가지치기의 목적은 지나치게 세분화된 가지를 잘라내어 <b>과대적합을 막고 일반화 성능을 높이는 것</b>입니다(2번). 트리를 더 깊고 복잡하게 만드는 것(3·4번)은 가지치기와 정반대 방향입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c48","number":55,"category":"빅데이터 모델링","type":"choice","subject":"<p>앙상블 기법 중 배깅과 부스팅의 학습 방식에 관한 설명 가운데 가장 적절한 것은?</p>","choices":[{"n":1,"html":"배깅에서는 편향이 최소화되며, 부스팅에서는 분산이 최소화된다."},{"n":2,"html":"여러 모델의 예측을 평균화함으로써 과적합을 줄이는 것이 부스팅이다."},{"n":3,"html":"오분류된 데이터에 가중치를 주어 정확도를 단계적으로 높이는 것이 배깅이다."},{"n":4,"html":"배깅에서는 분산이 최소화되며, 부스팅에서는 편향이 최소화된다."}],"answer":[4],"explain":{"mine":"<p>배깅은 여러 모델의 평균/투표로 <b>분산을 줄이고</b>, 부스팅은 오차를 순차적으로 보완하며 <b>편향을 줄입니다</b>(4번). 1번은 반대로 서술했고, 예측 평균화로 과적합을 줄이는 것은 배깅(2번 오답), 오분류 데이터 가중은 부스팅(3번 오답)의 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c38","number":56,"category":"빅데이터 모델링","type":"choice","subject":"<p>셋 이상의 집단들 사이에서 평균에 차이가 있는지를 검정하고자 할 때 이용하는 분석 방법은 무엇인가?</p>","choices":[{"n":1,"html":"회귀분석"},{"n":2,"html":"분산분석"},{"n":3,"html":"인과관계 분석"},{"n":4,"html":"주성분 분석"}],"answer":[2],"explain":{"mine":"<p>셋 이상 집단의 평균 차이를 검정하는 방법은 <b>분산분석(ANOVA)</b>입니다. 두 집단이면 t-검정을 쓰지만, 세 집단 이상에서 t-검정을 반복하면 제1종 오류가 누적되므로 분산분석으로 한 번에 검정합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c42","number":57,"category":"빅데이터 모델링","type":"choice","subject":"<p>입력 데이터를 압축했다가 다시 복원하는 비지도학습 기반의 인공신경망으로, 차원축소나 노이즈 제거, 이상치 탐지 등에 활용되는 것은 무엇인가?</p>","choices":[{"n":1,"html":"Gated Recurrent Unit"},{"n":2,"html":"Long Short-term Memory"},{"n":3,"html":"Autoencoder"},{"n":4,"html":"Deep Belief Network"}],"answer":[3],"explain":{"mine":"<p>입력을 저차원으로 <b>압축(인코더)했다가 다시 복원(디코더)</b>하도록 학습하는 비지도 신경망은 <b>오토인코더</b>입니다. 복원 오차를 최소화하며 학습하고, 차원축소·노이즈 제거·이상치 탐지(복원 오차가 큰 데이터 = 이상치)에 활용됩니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c39","number":58,"category":"빅데이터 모델링","type":"choice","subject":"<p>다음 중 로지스틱 회귀분석 모델에 관한 설명으로 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"종속변수가 두 개의 범주로 나누어져 있는 경우 조건부 확률은 정규분포를 따른다."},{"n":2,"html":"예측값을 확률로 변환할 때 시그모이드 함수를 이용한다."},{"n":3,"html":"이항형과 다항형으로 구분되며, 이항형일 때는 카테고리가 두 개로 나누어진다."},{"n":4,"html":"종속변수는 범주형이고, 독립변수로는 이산형 변수와 연속형 변수를 모두 사용할 수 있다."}],"answer":[1],"explain":{"mine":"<p>로지스틱 회귀에서 이진 종속변수의 조건부 분포는 정규분포가 아니라 <b>베르누이 분포</b>를 따릅니다. 1번이 옳지 않습니다. 시그모이드로 확률 변환, 이항형/다항형 구분, 독립변수로 이산·연속형 모두 사용 가능하다는 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c36","number":59,"category":"빅데이터 모델링","type":"choice","subject":"<p>변수 선택(Feature Selection) 기법에서 유의미한 변수를 골라낼 때 활용하는 통계량으로 보기 가장 어려운 것은 무엇인가?</p>","choices":[{"n":1,"html":"분산"},{"n":2,"html":"상호 정보량"},{"n":3,"html":"상관계수"},{"n":4,"html":"평균"}],"answer":[4],"explain":{"mine":"<p>분산(변별력 없는 저분산 변수 제거), 상관계수·상호 정보량(타깃과의 관련성 측정)은 변수 선택에 쓰이는 통계량입니다. <b>평균</b>은 변수의 위치만 알려줄 뿐 타깃과의 관련성이나 변별력에 대한 정보가 없어 변수 선택 기준으로 보기 어렵습니다(4번).</p>"}},{"id":"6a6a00651bbde79cd2c72c44","number":60,"category":"빅데이터 모델링","type":"choice","subject":"<p>확률적 경사하강법에 관한 설명 중 가장 적절하지 않은 것은 무엇인가?</p>","choices":[{"n":1,"html":"배치 하강법은 전체 데이터셋을 대상으로 적용되므로 수렴 속도가 느리고 메모리 사용량이 크다."},{"n":2,"html":"확률적 경사하강법은 배치 하강법과 비교할 때 지역 최솟값(Local Optimum)에 빠질 확률이 높다."},{"n":3,"html":"확률적 경사하강법의 수렴 경로는 배치 하강법에 비해 진동이 심하고 불안정하다."},{"n":4,"html":"확률적 경사하강법은 노이즈(손실함수의 울퉁불퉁함) 덕분에 전역 최적값을 찾을 가능성이 높다."}],"answer":[2],"explain":{"mine":"<p>확률적 경사하강법은 매 스텝의 노이즈(진동) 덕분에 오히려 <b>지역 최솟값을 탈출할 가능성이 높습니다</b>. '지역 최솟값에 빠질 확률이 높다'는 2번이 적절하지 않습니다 — 지역 최솟값에 갇히기 쉬운 쪽은 매끄럽게 수렴하는 배치 하강법입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4d","number":61,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>데이터 품질이 데이터 분석모형의 성능에 미치는 영향에 관한 설명 중 가장 적절한 것은?</p>","choices":[{"n":1,"html":"데이터 품질이 낮더라도 우수한 알고리즘을 개발하면 데이터 분석 모델의 일반화 성능을 높일 수 있다."},{"n":2,"html":"데이터 품질은 데이터 분석모형의 성능과 관련이 없다."},{"n":3,"html":"데이터 품질이 높을수록 노이즈까지 학습하게 되어 과대적합이 발생하고, 실제 의사결정에 유용한 인사이트를 제공하지 못한다."},{"n":4,"html":"데이터 품질이 우수할수록 데이터 분석 모델의 수준이 향상되어 일반화 성능이 좋아진다."}],"answer":[4],"explain":{"mine":"<p>모델 성능의 상한은 데이터 품질이 결정합니다('Garbage In, Garbage Out'). <b>품질이 우수할수록 일반화 성능이 좋아진다</b>는 4번이 적절합니다. 아무리 좋은 알고리즘도 저품질 데이터의 한계를 넘기 어렵고(1번 오답), 고품질 데이터가 과적합을 유발한다는 3번은 반대로 된 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4e","number":62,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>홀드아웃(Hold-out) 교차검증에 관한 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"구현 방식이 단순하고 계산 비용이 적게 들어 대용량 데이터셋에 효과적이다."},{"n":2,"html":"테스트 데이터는 모델 학습에 활용되지 않으므로 정보의 낭비가 생길 수 있다."},{"n":3,"html":"전체 데이터셋에서 검증 데이터를 따로 분리해 평가함으로써 모델의 성능을 일반화하는 기법을 사용하지 못한다."},{"n":4,"html":"전체 데이터를 학습용과 평가용으로 분할하여 모델을 학습시키고 검증한다."}],"answer":[3],"explain":{"mine":"<p>홀드아웃은 데이터를 학습용과 평가용으로 분리해 <b>일반화 성능을 평가하는 기법 그 자체</b>입니다. '일반화하는 기법을 사용하지 못한다'는 3번이 옳지 않습니다. 단순하고 계산이 적어 대용량에 효과적이라는 것, 테스트 데이터가 학습에 쓰이지 못해 데이터 낭비가 있다는 것은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c53","number":63,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 보기 가운데 과대적합을 방지하는 방법으로 보기 어려운 것은?</p>","choices":[{"n":1,"html":"ReLU 함수 사용"},{"n":2,"html":"드롭아웃 기법"},{"n":3,"html":"가중치 규제 적용"},{"n":4,"html":"배치 정규화 수행"}],"answer":[1],"explain":{"mine":"<p>드롭아웃, 가중치 규제(L1/L2), 배치 정규화는 과대적합 완화에 기여하는 기법들입니다. <b>ReLU는 기울기 소실 문제를 해결하기 위한 활성화 함수</b>일 뿐 과대적합 방지 기법이 아니므로 1번이 답입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c56","number":64,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>학습곡선(Learning Curve)을 통해 알 수 있는 학습 횟수와 데이터 분석 모델 성능 간의 관계에 대한 설명 중 옳은 것은?</p>","choices":[{"n":1,"html":"데이터에 대한 반복 학습이 진행될수록 검증 데이터의 오차(에러)는 일정 수준까지는 감소하나, 특정 지점을 지나면 다시 증가한다."},{"n":2,"html":"데이터에 대한 반복 학습이 진행될수록 학습 데이터의 오차(에러)는 증가한다."},{"n":3,"html":"학습 횟수가 증가하여 과적합이 발생할수록 검증 데이터에 대한 성능은 향상된다."},{"n":4,"html":"학습 횟수가 늘어날수록 테스트 데이터에 대한 성능은 검증 데이터의 성능과 큰 차이를 보이게 된다."}],"answer":[1],"explain":{"mine":"<p>학습곡선에서 <b>검증 오차는 학습이 진행되며 감소하다가, 과적합이 시작되는 지점부터 다시 증가</b>하는 U자 형태를 보입니다(1번). 학습 데이터의 오차는 계속 감소하고(2번 오답), 과적합이 생기면 검증 성능은 나빠집니다(3번 오답). 이 U자의 바닥이 조기 종료 시점입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4a","number":65,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>F1-score를 산출할 때 근거가 되는 두 가지 핵심 지표로 옳은 것은?</p>","choices":[{"n":1,"html":"정밀도, 재현율"},{"n":2,"html":"재현율, 특이도"},{"n":3,"html":"재현율, 정확도"},{"n":4,"html":"정밀도, 특이도"}],"answer":[1],"explain":{"mine":"<p>F1-score는 <b>정밀도(Precision)와 재현율(Recall)의 조화평균</b>입니다. 두 지표가 트레이드오프 관계이기 때문에 하나의 값으로 균형 있게 평가하기 위해 사용합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c58","number":66,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>그리드 탐색(Grid Search) 기법을 이용한 하이퍼파라미터 최적화에 관한 설명으로 가장 적절한 것은?</p>","choices":[{"n":1,"html":"지정된 범위 안에서 무작위 샘플링을 통해 조합을 골라 계산 비용을 절감한다."},{"n":2,"html":"가능한 하이퍼파라미터의 모든 조합을 빠짐없이 체계적으로 시도해 가며 최적 조합을 탐색한다."},{"n":3,"html":"이전의 평가 결과를 토대로 확률적 모델을 활용하여 유망한 파라미터 영역을 집중적으로 탐색한다."},{"n":4,"html":"모델 개발자가 하이퍼파라미터 값을 수동으로 정한 뒤 성능을 평가하는 과정을 반복적으로 수행한다."}],"answer":[2],"explain":{"mine":"<p>그리드 탐색은 지정한 하이퍼파라미터 후보들의 <b>모든 조합을 빠짐없이</b> 시도하는 방법입니다(2번). 1번은 무작위 탐색, 3번은 베이지안 최적화, 4번은 수동 탐색에 대한 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4c","number":67,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>빅데이터 분석 과정에서 데이터 품질과 관련된 설명 중 가장 적절하지 않은 것은?</p>","choices":[{"n":1,"html":"데이터 품질은 빅데이터 분석의 정확성에 직접적인 영향을 주지 않는다."},{"n":2,"html":"데이터 품질이 낮을 경우 데이터 분석결과의 신뢰성이 저하된다."},{"n":3,"html":"결측치 처리, 이상치 제거와 같은 전처리 작업은 데이터 품질관리를 위해 필요하다."},{"n":4,"html":"데이터 품질이 나쁠수록 문제 해결 과정은 한층 복잡해지고 어려워진다."}],"answer":[1],"explain":{"mine":"<p>데이터 품질은 분석의 정확성과 신뢰성에 <b>직접적인 영향을 미칩니다</b>. '직접적인 영향을 주지 않는다'는 1번이 적절하지 않습니다. 품질이 낮으면 결과 신뢰성이 떨어지고 문제 해결이 복잡해지며, 전처리는 품질관리의 핵심 작업입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4b","number":68,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>실젯값 x_i와 예측값 y_i 간의 오차를 측정하는 성능평가 지표 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"Mean Absolute Percentage Error(MAPE) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mrow><mo fence=\"true\">∣</mo><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub></mrow><msub><mi>x</mi><mi>i</mi></msub></mfrac></mstyle><mo fence=\"true\">∣</mo></mrow><mo>×</mo><mn>100</mn></mrow></semantics></math></span>"},{"n":2,"html":"Mean Percentage Error(MPE) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mrow><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub></mrow><msub><mi>x</mi><mi>i</mi></msub></mfrac></mstyle><mo>×</mo><mn>100</mn></mrow></semantics></math></span>"},{"n":3,"html":"Mean Absolute Error(MAE) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">∣</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy=\"false\">∣</mo></mrow></semantics></math></span>"},{"n":4,"html":"Mean Squared Error(MSE) = <span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mfrac><mn>1</mn><mi>n</mi></mfrac></mstyle><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>n</mi></msubsup><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math></span>"}],"answer":[4],"explain":{"mine":"<p>MSE는 오차의 <b>제곱</b>을 평균해야 하는데 4번 식에는 제곱이 빠져 있으므로 옳지 않습니다. 올바른 식은 (1/n)Σ(xᵢ−yᵢ)²입니다. MAPE(절대 백분율 오차 평균), MPE(백분율 오차 평균), MAE(절대 오차 평균)의 식은 모두 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c5a","number":69,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>두 변수 혹은 여러 변수 간의 상호 관계를 파악하고자 할 때 활용하는 관계 시각화 도구로 보기 어려운 것은 다음 중 무엇인가?</p>","choices":[{"n":1,"html":"파이 차트(Pie Chart)"},{"n":2,"html":"히트맵(Heat Map)"},{"n":3,"html":"버블 차트(Bubble Chart)"},{"n":4,"html":"산점도(Scatter Plot)"}],"answer":[1],"explain":{"mine":"<p>산점도·버블 차트·히트맵(상관행렬)은 변수 간 관계를 보여주는 관계 시각화 도구입니다. <b>파이 차트는 전체에서 각 부분이 차지하는 비율(구성)</b>을 보여주는 도구라 관계 시각화로 보기 어렵습니다(1번).</p>"}},{"id":"6a6a00651bbde79cd2c72c5c","number":70,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>인포그래픽(Infographics)에 관한 설명 중 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"시간과 이벤트를 시간의 흐름에 따라 나타내는 타임라인 시각화 기법도 활용된다."},{"n":2,"html":"인포그래픽의 표현 요소에는 텍스트도 포함된다."},{"n":3,"html":"인포그래픽은 데이터 시각화와 비슷하지만 서로 다른 개념으로 쓰이며, 주로 정량적 분석에 집중한다."},{"n":4,"html":"데이터 시각화와는 다르게 인포그래픽은 일반 대중이나 마케팅 타겟을 주된 대상으로 활용된다."}],"answer":[3],"explain":{"mine":"<p>인포그래픽은 정보의 <b>스토리텔링과 직관적 전달</b>에 초점을 두는 것이지 '정량적 분석에 집중'하는 것이 아니므로 3번이 옳지 않습니다. 데이터 시각화가 분석적·탐색적 도구라면, 인포그래픽은 일반 대중을 향한 커뮤니케이션 수단이라는 차이(4번)는 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c49","number":71,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>이진분류 모델에서 실제 값이 참인 데이터 가운데 모델이 참으로 올바르게 예측한 비율을 나타내는 지표는 무엇인가?</p>","choices":[{"n":1,"html":"정밀도"},{"n":2,"html":"정확도"},{"n":3,"html":"특이도"},{"n":4,"html":"민감도"}],"answer":[4],"explain":{"mine":"<p>실제 참(Positive)인 것들 가운데 모델이 참으로 맞게 예측한 비율은 <b>민감도(Sensitivity)</b> = TP/(TP+FN)이며, 재현율(Recall)과 같은 지표입니다. 정밀도는 '참이라고 예측한 것 중 실제 참'의 비율이라는 점에서 방향이 다릅니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c5b","number":72,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>아래 보기에서 설명하고 있는 시각화 기법으로 가장 적절한 것은?</p><div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>복잡한 통계 데이터를 직관적으로 파악할 수 있도록 돕는다.</li><li>데이터 값에 비례하도록 영역의 크기를 변형해 나타낸다.</li><li>기존 지도의 기하학적 정확성을 포기하는 대신 데이터의 상대적 중요성을 부각한다.</li><li>지리적 영역이 왜곡되므로 실제 위치나 형태를 나타내려는 경우에는 주의가 필요하다.</li></ul></div>","choices":[{"n":1,"html":"카토그램(Cartogram)"},{"n":2,"html":"히트맵(Heat Map)"},{"n":3,"html":"체르노프 페이스(Chernoff Faces)"},{"n":4,"html":"거미줄 차트(Spider Chart)"}],"answer":[1],"explain":{"mine":"<p>데이터 값에 비례해 <b>지역의 면적을 왜곡</b>해 그리는 지도 기반 시각화는 <b>카토그램</b>입니다. 인구수에 비례해 국가 크기를 다시 그린 세계지도가 대표적인 예로, 기하학적 정확성 대신 데이터의 상대적 중요성을 부각합니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c55","number":73,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>모델 성능 평가와 교차검증 기법에 관한 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"모델 복잡도는 주로 교차검증에서 검증에러가 최소가 되는 지점을 기준으로 선택한다."},{"n":2,"html":"검증 데이터에 대한 성능이 수렴되면 더 이상 학습이 불가능하다."},{"n":3,"html":"모델의 일반화 성능을 평가하는 목적으로 교차검증이 주로 활용된다."},{"n":4,"html":"모델의 복잡도가 커질수록 학습 오차는 줄어들지만, 검증 오차는 U자 형태를 보인다."}],"answer":[2],"explain":{"mine":"<p>검증 성능이 수렴했다고 해서 <b>학습이 불가능해지는 것은 아닙니다</b> — 학습은 계속할 수 있으나 성능 개선이 없을 뿐이고, 계속하면 과적합으로 오히려 나빠질 수 있습니다(2번이 옳지 않음). 검증 에러 최소 지점으로 모델 복잡도를 고르고, 검증 오차가 U자를 그린다는 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c50","number":74,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>하이퍼파라미터가 10개이고 10-fold 교차검증 기법을 사용할 때, 아래의 각 분석모형과 그 학습 횟수가 바르게 연결된 것은? (단, 로지스틱 회귀분석과 QDA의 경우 하이퍼파라미터 튜닝 없이 기본 값을 그대로 사용한다)</p>","choices":[{"n":1,"html":"라쏘 회귀분석 : 100회"},{"n":2,"html":"로지스틱 회귀분석 : 100회"},{"n":3,"html":"QDA(Quadratic Discriminant Analysis) : 100회"},{"n":4,"html":"K-NN : 50회"}],"answer":[1],"explain":{"mine":"<p>하이퍼파라미터 후보 10개 × 10-fold = <b>라쏘 100회</b>가 맞습니다(1번). 로지스틱 회귀와 QDA는 튜닝 없이 기본값을 쓴다고 했으므로 10-fold만 수행해 10회씩이고, K-NN은 K 후보 10개를 튜닝하면 100회입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c59","number":75,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>공간 시각화에 관한 다음 설명 가운데 옳지 않은 것을 고르면?</p>","choices":[{"n":1,"html":"히트맵을 활용하면 특정 생물종의 출현 빈도, 서식지 집중도 등 생태 정보를 나타낼 때 해당 지역의 밀도나 강도를 색상으로 표현할 수 있다."},{"n":2,"html":"좌푯값이 있는 데이터는 지도상에 시각화할 때 더욱 직관적으로 표현할 수 있다."},{"n":3,"html":"단계 구분도(Choropleth Map)는 계단식으로 구성되어 있어, 계단식 표현과 직접적인 연관성을 지닌다."},{"n":4,"html":"주소나 장소 이름을 지리적 좌표(위도, 경도)로 변환하는 기술을 Geocoding이라고 한다."}],"answer":[3],"explain":{"mine":"<p>단계 구분도(Choropleth Map)는 지역별 값을 <b>색상의 단계(음영)</b>로 표현하는 지도이지, '계단식 구성'과는 관련이 없습니다(3번이 옳지 않음). 인구밀도·투표율 지도가 대표적 예입니다. 히트맵의 밀도 표현, 좌표 데이터의 지도 시각화, Geocoding 설명은 맞습니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c51","number":76,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 보기 중 데이터가 정규분포를 따르는지 확인하는 방법으로 가장 거리가 먼 것은?</p>","choices":[{"n":1,"html":"Q-Q Plot"},{"n":2,"html":"Shapiro-Wilk Test"},{"n":3,"html":"Kolmogorov-Smirnov Test"},{"n":4,"html":"t-Test"}],"answer":[4],"explain":{"mine":"<p>정규성 확인에는 Q-Q Plot(시각적), Shapiro-Wilk, Kolmogorov-Smirnov(검정)를 사용합니다. <b>t-Test는 평균 차이를 검정</b>하는 방법이지 정규성 확인 방법이 아니므로 4번이 답입니다(오히려 t-검정이 정규성을 전제로 합니다).</p>"}},{"id":"6a6a00651bbde79cd2c72c52","number":77,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>과대적합과 과소적합에 관한 다음 설명 중 옳지 않은 것은?</p>","choices":[{"n":1,"html":"과소적합이 일어나면 훈련 데이터에 대한 예측력이 부족해진다."},{"n":2,"html":"과대적합이 일어나면 새로운 평가 데이터에 대한 예측 성능이 저하된다."},{"n":3,"html":"복잡한 모델은 데이터의 수가 적을 때 과대적합이 발생할 위험이 있다."},{"n":4,"html":"과소적합이 일어나면 평가용 데이터에 대한 성능은 개선된다."}],"answer":[4],"explain":{"mine":"<p>과소적합은 모델이 데이터의 패턴 자체를 못 잡은 상태라 훈련·평가 데이터 <b>모두에서 성능이 낮습니다</b>. '평가 데이터 성능은 개선된다'는 4번이 옳지 않습니다. 과대적합 시 새 데이터 성능 저하, 데이터가 적을 때 복잡한 모델의 과적합 위험은 맞는 설명입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c4f","number":78,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>LOOCV(Leave-one-out Cross Validation) 교차검증 기법에 관한 설명 중 옳은 것은 무엇인가?</p>","choices":[{"n":1,"html":"n개의 전체 데이터 가운데 반복할 때마다 데이터 한 개를 검증용(Test)으로 두고, 남은 n-1개를 학습에 활용한다."},{"n":2,"html":"n개의 전체 데이터를 동일한 크기의 K개 Fold로 구성한다."},{"n":3,"html":"n개의 전체 데이터를 학습용(Train)과 검증용(Test)으로 단 한 차례만 분할하여 활용한다."},{"n":4,"html":"n개의 전체 데이터 가운데 p개를 테스트셋으로 두고 나머지를 학습에 활용한다."}],"answer":[1],"explain":{"mine":"<p>LOOCV는 매 반복마다 <b>데이터 1개만 검증용</b>으로 남기고 나머지 n−1개로 학습하며, 이를 n번 반복하는 방법입니다(1번). K개 Fold로 나누는 것은 K-fold(2번), 한 번만 분할은 홀드아웃(3번), p개를 남기는 것은 LpOCV(4번)입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c57","number":79,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>다음 보기 가운데 하이퍼파라미터(초매개변수)에 해당하는 것은?</p>","choices":[{"n":1,"html":"SVM에서의 서포트벡터"},{"n":2,"html":"K-NN에서의 군집의 개수"},{"n":3,"html":"선형회귀에서의 가중치"},{"n":4,"html":"인공신경망에서의 가중치"}],"answer":[2],"explain":{"mine":"<p>K-NN의 <b>K(참조할 이웃의 개수)</b>는 학습 전에 사람이 정하는 하이퍼파라미터입니다(2번). 서포트벡터는 학습 결과 결정되는 데이터 포인트이고, 선형회귀·신경망의 가중치는 학습으로 얻어지는 파라미터입니다.</p>"}},{"id":"6a6a00651bbde79cd2c72c54","number":80,"category":"빅데이터 결과 해석","type":"choice","subject":"<p>규제(Regularization)와 과대적합에 관한 설명 중 가장 옳지 않은 것을 고르시오.</p>","choices":[{"n":1,"html":"적절한 가중치를 반영하여 규제를 적절히 적용하면 일반화 성능이 향상된다."},{"n":2,"html":"규제가 강하면 모델이 지나치게 단순해진다."},{"n":3,"html":"규제가 약하면 모델이 복잡해져서 일반화 성능이 떨어진다."},{"n":4,"html":"규제를 약하게 적용할수록 과적합의 위험이 줄어든다."}],"answer":[4],"explain":{"mine":"<p>규제를 <b>약하게</b> 하면 모델이 복잡해져 과적합 위험이 <b>커집니다</b>. '약할수록 과적합 위험이 줄어든다'는 4번이 옳지 않습니다. 규제가 너무 강하면 과소적합(지나친 단순화), 적절하면 일반화 향상이라는 설명은 맞습니다.</p>"}}]};